// 1. Obtener todos los items de entrada desde el nodo anterior
const items = $input.all();

// 2. Inicializar el array de salida
const outputItems = [];

// 3. Procesar cada item
for (const item of items) {
  try {
    const inputJson = item.json;

    // Asegurarse de que el campo input existe y tiene la estructura esperada
    if (!inputJson || !inputJson.message || typeof inputJson.message.content !== 'string') {
      throw new Error("La estructura 'message.content' no se encontró o no es un string.");
    }

    // Parsear el contenido JSON de 'message.content'
    const parsedContent = JSON.parse(inputJson.message.content);

    // Obtener el valor original del campo 'chunk' (puede venir de un nodo anterior)
    const originalChunk = inputJson.chunk !== undefined ? inputJson.chunk : null;

    // Construir el nuevo objeto JSON de salida
    const newOutputJson = {
      ...parsedContent,
      chunk: originalChunk
    };

    // Añadirlo al array de salida
    outputItems.push({ json: newOutputJson });

  } catch (error) {
    // Capturar errores y generar una salida de error clara
    outputItems.push({
      json: {
        error: "Fallo al procesar el item",
        details: error.message,
        originalInput: item.json
      }
    });
  }
}

// 4. Devolver todos los objetos transformados
return outputItems;

// ✅ Paso 1: Obtener el texto desde la variable de entrada JSON.
// Si no existe, usamos un string vacío para evitar errores.
const text = $json.text || '';

// ✅ Paso 2: Limpiar el texto para facilitar el procesamiento.
// - normalize("NFD"): separa letras y tildes (ej. "á" -> "a" + tilde).
// - replace: elimina saltos de línea (\n), retornos (\r), tabulaciones (\t) y espacios duplicados.
const cleanText = text.normalize("NFD")
  .replace(/[\n\r\t]+/g, ' ')
  .replace(/\s{2,}/g, ' ');

// ✅ Paso 3: Dividir el texto en frases.
// Usamos una expresión regular que detecta final de frase (., ?, ! seguidos de espacio).
const sentences = cleanText.split(/(?<=[.?!])\s+/);

// ✅ Paso 4: Preparar variables
const chunks = [];         // Aquí guardaremos los fragmentos resultantes
let currentChunk = [];     // Acumula frases hasta llegar al límite
let charCursor = 0;        // Nos ayuda a encontrar la posición exacta del fragmento en el texto original

// ✅ Paso 5: Recorrer todas las frases una a una
for (let i = 0; i < sentences.length; i++) {
  const sentence = sentences[i];
  currentChunk.push(sentence); // Añadir frase al bloque actual

  // Si el bloque tiene al menos 3 frases o supera los 500 caracteres, lo cortamos aquí
  if (currentChunk.length >= 3 || currentChunk.join(" ").length > 500) {
    const chunkText = currentChunk.join(" ");           // Convertimos el bloque en texto completo
    const searchText = chunkText.slice(0, 30);          // Cogemos los primeros 30 caracteres para buscarlo en el texto original
    const matchPos = cleanText.indexOf(searchText, charCursor); // Buscamos el fragmento en el texto original desde la última posición

    const startIndex = matchPos > -1 ? matchPos : null; // Si lo encontramos, guardamos la posición

    // Guardamos el bloque en la lista de chunks
    chunks.push({
      chunk: chunkText,
      startIndex: startIndex,
    });

    // Avanzamos el cursor si encontramos la posición
    if (matchPos > -1) charCursor = matchPos + chunkText.length;

    // Reseteamos el bloque actual para seguir con el siguiente
    currentChunk = [];
  }
}

// ✅ Paso 6: Guardar el último fragmento que haya quedado pendiente
if (currentChunk.length) {
  const chunkText = currentChunk.join(" ");
  const searchText = chunkText.slice(0, 30);
  const matchPos = cleanText.indexOf(searchText, charCursor);
  const startIndex = matchPos > -1 ? matchPos : null;

  chunks.push({
    chunk: chunkText,
    startIndex: startIndex,
  });
}

// ✅ Paso 7: Devolver los resultados en el formato que espera n8n
// Cada fragmento se envuelve dentro de un objeto { json: ... }
return chunks.map(c => ({ json: c }));

// ✅ 1) Función para limpiar texto antes de enviarlo a la API
// Esta función se asegura de que el chunk no tenga símbolos extraños, comillas problemáticas o caracteres invisibles.
const cleanText = (text) => {
  if (typeof text !== 'string') return ''; // Si no es un string, devolvemos vacío

  return text
    .replace(/[\n\r\t]+/g, ' ')             // Elimina saltos de línea, retornos y tabulaciones
    .replace(/[""«»'']/g, ' ')              // Reemplaza comillas dobles, comillas angulares y simples
    .replace(/[–—]/g, '-')                  // Reemplaza guiones largos por guiones normales
    .replace(/[•·]/g, '-')                  // Reemplaza bullets por guiones
    .replace(/\s{2,}/g, ' ')                // Reemplaza espacios múltiples por un solo espacio
    .replace(/\\(?=[^"\\/bfnrtu])|\\$/g, '')// Elimina barras invertidas inválidas en JSON
    .trim();                                // Quita espacios al principio y al final
};

// ✅ 2) Recorremos cada item del flujo (cada chunk generado anteriormente)
return items.map(item => {
  // Obtenemos el chunk crudo desde el nodo anterior llamado "Loop Over Items"
  const rawChunk = $node["Loop Over Items1"].json.chunk;

  // ✅ 3) Limpiamos el chunk usando la función anterior
  const cleaned = cleanText(rawChunk);

  // ✅ 4) Escapamos el texto para que sea válido en JSON:
  // - JSON.stringify escapa todo (comillas, saltos, etc.)
  // - Luego le quitamos las comillas exteriores que JSON.stringify añade al principio y final
  const escaped = JSON.stringify(cleaned).slice(1, -1);

  // ✅ 5) Guardamos el texto limpio y escapado en el campo `chunk` del item actual
  item.json.chunk = escaped;

  // Devolvemos el item actualizado
  return item;
});

// ✅ 1) Obtener el texto desde la variable de entrada.
// Si no existe, usamos un string vacío para evitar errores.
const text = $json.text || '';

// ✅ 2) Dividir el texto en frases completas.
// Usamos una expresión regular que detecta puntos, interrogaciones o exclamaciones seguidos de espacios.
// Esto nos da una lista de frases del texto.
const sentences = text.split(/(?<=[.?!])\s+/);

// ✅ 3) Preparar las variables
const chunks = [];         // Aquí guardaremos los bloques finales
let currentChunk = [];     // Este array irá acumulando frases

// ✅ 4) Recorremos cada frase del texto
for (let i = 0; i < sentences.length; i++) {
  currentChunk.push(sentences[i]); // Añadimos la frase actual al bloque

  // Si ya tenemos 3 frases o más de 500 caracteres, guardamos este bloque
  if (currentChunk.length >= 3 || currentChunk.join(" ").length > 500) {
    chunks.push({
      chunk: currentChunk.join(" ") // Unimos las frases en un solo texto
    });
    currentChunk = []; // Empezamos un nuevo bloque
  }
}

// ✅ 5) Si queda algún fragmento pendiente al final, también lo añadimos
if (currentChunk.length) {
  chunks.push({
    chunk: currentChunk.join(" ")
  });
}

// ✅ 6) Devolver los bloques (chunks) en el formato que espera n8n
// Cada uno debe ir dentro de un objeto { json: ... }
return chunks.map(c => ({ json: c }));

// ✅ 1) Creamos una función para limpiar el texto de un chunk
// Esta función se asegura de que el texto esté limpio, legible y sin caracteres raros
const cleanText = (text) => {
  if (typeof text !== 'string') return ''; // Si no es un texto válido, devolvemos una cadena vacía

  return text
    .replace(/[\n\r\t]+/g, ' ')              // Elimina saltos de línea, retornos de carro y tabulaciones
    .replace(/[“”«»‘’]/g, '"')               // Sustituye comillas raras por comillas normales dobles (")
    .replace(/[–—]/g, '-')                   // Reemplaza guiones largos o extraños por guiones estándar
    .replace(/[•·]/g, '-')                   // Reemplaza bullets por guiones
    .replace(/\s{2,}/g, ' ')                 // Reduce múltiples espacios a un solo espacio
    .trim();                                 // Elimina espacios al principio y al final del texto
};

// ✅ 2) Recorremos cada item del flujo (normalmente cada uno es un fragmento o "chunk")
return items.map(item => {
  // Limpiamos el campo `chunk` usando la función anterior
  item.json.chunk = cleanText(item.json.chunk);

  // Devolvemos el item modificado
  return item;
});

